import {labDefs} from './import.mjs';
import {getLocale} from './i18n.mjs';
import {emptyReferenceProfile,validateReferenceProfile,evaluateReferenceProfile,restoreReferenceProfile} from './lab-reference-ranges.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={albumin:['Albumin','Albümin'],neutrophils:['Absolute neutrophils','Mutlak nötrofil'],lymphocytes:['Absolute lymphocytes','Mutlak lenfosit'],crp:['CRP','CRP'],creatinine:['Creatinine','Kreatinin'],lactate:['Lactate','Laktat'],potassium:['Potassium','Potasyum'],phosphate:['Phosphate','Fosfat'],magnesium:['Magnesium','Magnezyum'],uun:['Urinary urea nitrogen · 24 h','İdrar üre azotu · 24 saat']};
const storageKey='nutriklinik.clinic-reference-profile.v1';
// Recovery of an unfinished local form is separate from importing an approved
// profile. Invalid scalar entries remain visible and invalid; no applicability
// or comparison result is restored as authority.
function referenceDraftProfile(data){
 const profile=emptyReferenceProfile(),raw=data?.profile;let unsupported=false;
 const object=value=>value!==null&&typeof value==='object'&&!Array.isArray(value);
 const scalar=value=>value===null||typeof value==='boolean'||typeof value==='number'&&Number.isFinite(value)||typeof value==='string'&&value.length<=4096;
 if(!object(raw))return profile;
 const fields=['schemaVersion','clinicName','source','version','effectiveFrom','effectiveTo','ageMin','ageMax','sex'];
 for(const key of Object.keys(raw))if(![...fields,'rows'].includes(key))unsupported=true;
 for(const key of fields)if(Object.hasOwn(raw,key)){if(scalar(raw[key]))profile[key]=raw[key];else unsupported=true;}
 if(object(raw.rows)){
  for(const key of Object.keys(raw.rows))if(!Object.hasOwn(labDefs,key))unsupported=true;
  for(const key of Object.keys(labDefs))if(Object.hasOwn(raw.rows,key)){
   const row=raw.rows[key];if(!object(row)){unsupported=true;continue;}
   for(const field of Object.keys(row))if(!['enabled','lower','upper','unit'].includes(field))unsupported=true;
   for(const field of ['enabled','lower','upper','unit'])if(Object.hasOwn(row,field)){if(scalar(row[field]))profile.rows[key][field]=row[field];else unsupported=true;}
  }
 }else if(Object.hasOwn(raw,'rows'))unsupported=true;
 if(unsupported)profile.schemaVersion='invalid-local-draft';
 return profile;
}
export function initLabReferences({containerId='clinicReferences',getInput,onChange=()=>{},downloadProfile}){
 const $=id=>document.getElementById(id),T=(en,tr)=>getLocale()==='tr'?tr:en;
 let profile=emptyReferenceProfile(),confirmed=false,language='',notice='',importGeneration=0,editorOpen=false;
 try{const saved=localStorage.getItem(storageKey);if(saved){profile=restoreReferenceProfile(JSON.parse(saved));notice='saved';}}catch{notice='storage-unavailable';}
 const label=key=>T(...(names[key]||[key,key]));
 const units=key=>[labDefs[key].unit,...(key==='albumin'?['g/dL']:['neutrophils','lymphocytes'].includes(key)?['cells/µL']:key==='potassium'?['mEq/L']:[])];
 const input=(id,title,type='text',extra='')=>`<div class="field"><label for="ref-${id}">${title}</label><input id="ref-${id}" data-reference-meta="${id}" type="${type}" ${extra} value="${esc(profile[id]??'')}" autocomplete="off"></div>`;
 function forms(){
  const target=$(containerId);if(!target)return;
  target.innerHTML=`<div class="card-head"><div><span class="eyebrow">${T('CLINIC LABORATORY SETTINGS','KLİNİK LABORATUVAR AYARLARI')}</span><h2>${T('Your laboratory reference intervals','Kendi laboratuvar referans aralıklarınız')}</h2></div></div><p>${T('Enter the intervals issued by your laboratory for its assay and reference population. Values stay local. Do not enter patient identifiers in this clinic profile.','Laboratuvarınızın yöntem ve referans popülasyonu için bildirdiği aralıkları girin. Veriler yereldir. Bu klinik profiline hasta kimliği yazmayın.')}</p><p class="footnote">${T('These bounds describe laboratory context. They do not redefine safety limits, GLIM/organ-score criteria, a catabolic/anabolic diagnosis or a nutrition dose.','Bu sınırlar laboratuvar bağlamını gösterir. Güvenlik sınırlarını, GLIM/organ puanı ölçütlerini, katabolik/anabolik tanıyı veya beslenme dozunu yeniden tanımlamaz.')}</p>
   <details id="referenceEditor" class="reference-editor" ${editorOpen?'open':''}><summary>${T('Configure clinic intervals','Klinik aralıklarını düzenle')}</summary><div class="fields reference-profile-fields">${input('clinicName',T('Hospital / laboratory','Hastane / laboratuvar'),'text','maxlength="160"')}${input('source',T('Assay / source document','Yöntem / kaynak belge'),'text','maxlength="500"')}${input('version',T('Profile version','Profil sürümü'),'text','maxlength="80"')}${input('effectiveFrom',T('Valid from','Geçerlilik başlangıcı'),'date')}${input('effectiveTo',T('Valid until · optional','Geçerlilik sonu · isteğe bağlı'),'date')}${input('ageMin',T('Minimum age (years)','En düşük yaş (yıl)'),'number','min="18" max="120" step="any"')}${input('ageMax',T('Maximum age (years)','En yüksek yaş (yıl)'),'number','min="18" max="120" step="any"')}<div class="field"><label for="ref-sex">${T('Recorded-sex applicability','Kaydedilen cinsiyete uygunluk')}</label><select id="ref-sex" data-reference-meta="sex">${[['all',T('All recorded sexes','Tüm kaydedilen cinsiyetler')],['female',T('Female','Kadın')],['male',T('Male','Erkek')]].map(([v,t])=>`<option value="${v}" ${profile.sex===v?'selected':''}>${t}</option>`).join('')}</select></div></div>
   <div class="reference-rows">${Object.keys(labDefs).map(key=>{const row=profile.rows[key];return `<section class="reference-row"><label class="check-field"><input type="checkbox" data-reference-enabled="${key}" ${row.enabled?'checked':''}><strong>${esc(label(key))}</strong></label><div class="reference-bounds"><div class="field"><label for="ref-${key}-lower">${T('Lower bound','Alt sınır')}</label><input id="ref-${key}-lower" data-reference-row="${key}" data-reference-bound="lower" type="number" min="0" step="any" value="${esc(row.lower??'')}"></div><div class="field"><label for="ref-${key}-upper">${T('Upper bound','Üst sınır')}</label><input id="ref-${key}-upper" data-reference-row="${key}" data-reference-bound="upper" type="number" min="0" step="any" value="${esc(row.upper??'')}"></div><div class="field"><label for="ref-${key}-unit">${T('Unit','Birim')}</label><select id="ref-${key}-unit" data-reference-row="${key}" data-reference-bound="unit">${units(key).map(v=>`<option value="${esc(v)}" ${row.unit===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div></div>${key==='uun'?`<p class="footnote">${T('Requires its own dated, confirmed complete urine collection. A laboratory interval is not nitrogen balance or muscle anabolism.','Kendi tarihli, tam olduğu doğrulanmış idrar toplaması gerekir. Laboratuvar aralığı azot dengesi veya kas anabolizması değildir.')}</p>`:''}</section>`;}).join('')}</div>
   <label class="check-field"><input id="referenceApplicable" type="checkbox" ${confirmed?'checked':''}><span>${T('I verified this profile against the laboratory source and confirmed that its age, recorded sex, specimen, method and validity dates apply to this patient.','Bu profili laboratuvar kaynağıyla kontrol ettim; yaş, kaydedilen cinsiyet, örnek, yöntem ve geçerlilik tarihlerinin bu hastaya uygunluğunu doğruladım.')}</span></label>
   <div class="button-row"><button type="button" id="saveReferenceProfile" class="button secondary">${T('Save clinic profile on this device','Klinik profilini bu cihaza kaydet')}</button><button type="button" id="exportReferenceProfile" class="button secondary">${T('Export clinic profile · JSON','Klinik profilini dışa aktar · JSON')}</button><label class="button secondary" for="referenceProfileFile">${T('Import clinic profile · JSON','Klinik profilini içe aktar · JSON')}</label><input id="referenceProfileFile" class="file-input" type="file" accept=".json,application/json"></div><p class="footnote">${T('Only clinic settings are saved on this device; patient measurements and applicability confirmation are excluded. Export and import this profile to reuse it at another workstation.','Bu cihaza yalnız klinik ayarları kaydedilir; hasta ölçümleri ve uygunluk onayı kaydedilmez. Profili başka bilgisayarda kullanmak için dışa/içe aktarın.')}</p></details><p class="footnote"><a href="./CLINIC-REFERENCE-INTERVALS.md" download="CLINIC-REFERENCE-INTERVALS.md">${T('Clinic interval methods and limits ↓','Klinik aralıklarının yöntemi ve sınırları ↓')}</a></p><p id="referenceProfileStatus" role="status" class="footnote"></p><div id="referenceResults" aria-live="polite"></div>`;
  $('referenceEditor').addEventListener('toggle',e=>{editorOpen=e.target.open;});
  for(const el of target.querySelectorAll('[data-reference-meta],[data-reference-row],[data-reference-enabled]'))el.addEventListener(el.tagName==='SELECT'||el.type==='checkbox'?'change':'input',()=>{importGeneration++;if(el.dataset.referenceMeta)profile[el.dataset.referenceMeta]=el.value;else if(el.dataset.referenceEnabled)profile.rows[el.dataset.referenceEnabled].enabled=el.checked;else profile.rows[el.dataset.referenceRow][el.dataset.referenceBound]=el.value;confirmed=false;$('referenceApplicable').checked=false;notice='';onChange();});
  $('referenceApplicable').addEventListener('change',e=>{confirmed=e.target.checked;onChange();});
  $('saveReferenceProfile').addEventListener('click',()=>{const valid=validateReferenceProfile(profile);if(!valid.valid){notice='invalid';refresh();return;}try{localStorage.setItem(storageKey,JSON.stringify(valid.profile));notice='stored';}catch{notice='storage-unavailable';}refresh();});
  $('exportReferenceProfile').addEventListener('click',()=>{const valid=validateReferenceProfile(profile);if(!valid.valid){notice='invalid';refresh();return;}downloadProfile?.(valid.profile);notice='exported';refresh();});
  $('referenceProfileFile').addEventListener('change',async e=>{const generation=++importGeneration,file=e.target.files?.[0];if(!file)return;try{if(file.size>262144)throw Error('size');const parsed=JSON.parse(await file.text());if(generation!==importGeneration)return;const valid=validateReferenceProfile(parsed);if(!valid.valid)throw Error('invalid');profile=restoreReferenceProfile(parsed);confirmed=false;notice='imported';language='';forms();onChange();}catch{if(generation===importGeneration){notice='import-error';refresh();}}finally{if(generation===importGeneration&&$('referenceProfileFile'))$('referenceProfileFile').value='';}});
  language=getLocale();
 }
 function refresh(){if(language!==getLocale())forms();if(!$('referenceResults'))return;
  const validation=validateReferenceProfile(profile),evaluation=evaluateReferenceProfile(getInput(),profile,{applicabilityConfirmed:confirmed});
  const messages={saved:T('Saved clinic settings loaded. Verify applicability for this patient.','Kayıtlı klinik ayarları yüklendi. Bu hasta için uygunluğu doğrulayın.'),stored:T('Clinic settings saved locally. Patient values were not saved.','Klinik ayarları yerel kaydedildi. Hasta değerleri kaydedilmedi.'),exported:T('Clinic profile exported.','Klinik profili dışa aktarıldı.'),imported:T('Profile imported; patient applicability requires confirmation.','Profil içe aktarıldı; hastaya uygunluk onayı gerekiyor.'),'draft-restored':T('Local form draft restored. Verify source and patient applicability again.','Yerel form taslağı geri açıldı. Kaynak ve hastaya uygunluğu yeniden doğrulayın.'),invalid:T('Correct the profile fields before saving or exporting.','Kaydetmeden veya dışa aktarmadan önce profil alanlarını düzeltin.'),'storage-unavailable':T('Device storage is unavailable. You can export a valid profile instead.','Cihaz kaydı kullanılamıyor. Geçerli profili dışa aktarabilirsiniz.'),'import-error':T('Profile was not imported: invalid schema/fields or file larger than 256 KB.','Profil içe aktarılmadı: geçersiz şema/alanlar veya 256 KB üzerinde dosya.')};
  $('referenceProfileStatus').textContent=messages[notice]||'';
  const reasonText=Object.fromEntries([
 ['row-disabled','No interval enabled','Aralık etkin değil'],['invalid-profile','Complete or correct the clinic profile','Klinik profilini tamamlayın veya düzeltin'],
 ['applicability-unconfirmed','Confirm applicability for this patient','Bu hasta için uygunluğu doğrulayın'],['invalid-error-metadata','Review measurement error metadata','Ölçüm hata bilgisini gözden geçirin'],
 ['flagged-input','Correct flagged input fields','İşaretlenen girdileri düzeltin'],['laboratory-unconfirmed','Confirm the laboratory measurements','Laboratuvar ölçümlerini doğrulayın'],
 ['invalid-patient-age','Enter a valid adult age','Geçerli yetişkin yaşı girin'],['age-mismatch','Patient age is outside this profile','Hasta yaşı bu profilin dışında'],
 ['invalid-patient-sex','Recorded sex is missing or unspecified','Kaydedilen cinsiyet eksik veya belirtilmemiş'],['sex-mismatch','Recorded sex does not match this profile','Kaydedilen cinsiyet bu profile uymuyor'],
 ['invalid-patient-date','Review specimen and assessment dates','Örnek ve değerlendirme tarihlerini kontrol edin'],['specimen-after-assessment','Specimen date is after the assessment','Örnek tarihi değerlendirmeden sonra'],
 ['profile-date-mismatch','Profile is not valid on this specimen date','Profil bu örnek tarihinde geçerli değil'],['collection-unconfirmed','Confirm the complete urine collection','Tam idrar toplamasını doğrulayın'],
 ['missing-measurement','Measurement is missing','Ölçüm eksik'],['invalid-measurement','Review the value and unit','Değeri ve birimi kontrol edin'],
 ['invalid-collection-time','Enter valid urine collection timestamps','Geçerli idrar toplama zamanlarını girin'],
 ['mixed-collection-time-basis','Use the same time basis for collection start and end','Toplama başlangıç ve bitişinde aynı zaman temelini kullanın'],
 ['invalid-collection-duration','A complete 24-hour collection is required','Tam 24 saatlik toplama gerekir'],
 ['collection-date-mismatch','The urine specimen date must match the written collection-end date','İdrar örnek tarihi yazılan toplama bitiş tarihiyle eşleşmeli'],
 ['invalid-urine-volume','Enter a positive measured urine volume','Pozitif ölçülmüş idrar hacmini girin']
 ].map(([key,en,tr])=>[key,T(en,tr)]));
  const statusText={below:T('Below entered interval','Girilen aralığın altında'),within:T('Within entered bounds','Girilen sınırlar içinde'),above:T('Above entered interval','Girilen aralığın üstünde'),unavailable:T('Unavailable / verification required','Kullanılamıyor / doğrulama gerekli'),'not-applicable':T('Profile does not apply','Profil uygun değil'),disabled:T('No interval entered','Aralık girilmedi')};
  const metadataNames={clinicName:T('Hospital / laboratory','Hastane / laboratuvar'),source:T('Assay / source document','Yöntem / kaynak belge'),version:T('Profile version','Profil sürümü'),effectiveFrom:T('Valid from','Geçerlilik başlangıcı'),effectiveTo:T('Valid until','Geçerlilik sonu'),ageMin:T('Minimum age','En düşük yaş'),ageMax:T('Maximum age','En yüksek yaş'),sex:T('Recorded-sex applicability','Kaydedilen cinsiyete uygunluk')};
  const errorText=e=>{const parts=e.path.split('.'),title=metadataNames[e.path]||(parts[0]==='rows'?label(parts[1]):T('Clinic profile','Klinik profili'));return title+': '+T('review required fields, dates, units and ordered bounds','gerekli alanları, tarihleri, birimleri ve sıralı sınırları kontrol edin');};
  const enabled=evaluation.results.filter(r=>profile.rows[r.analyte]?.enabled);
  $('referenceResults').innerHTML=`<h3>${T('Patient results against clinic intervals','Hasta sonuçları ve klinik aralıkları')}</h3>${!validation.valid&&(enabled.length||profile.clinicName||profile.source||profile.version||notice==='invalid')?`<p class="reference-warning">${T('Profile incomplete or invalid. No normal/abnormal classification is authorized.','Profil eksik veya geçersiz. Normal/anormal sınıflandırması yapılamaz.')} ${validation.errors.map(e=>esc(errorText(e))).join(' · ')}</p>`:''}${!confirmed?`<p class="footnote">${T('Confirm source and patient applicability above. Verify the sample dates and measurements in the main laboratory form.','Yukarıdan kaynak ve hastaya uygunluğu doğrulayın. Ana laboratuvar formunda örnek tarihlerini ve ölçümleri doğrulayın.')}</p>`:''}${enabled.length?`<div class="reference-result-grid">${enabled.map(r=>`<article class="reference-result" data-reference-status="${esc(r.status)}"><strong>${esc(label(r.analyte))}</strong><span>${r.value==null?'—':esc(r.value)} ${esc(r.unit||labDefs[r.analyte].unit)}</span><span>${r.lower==null?'—':esc(r.lower)} – ${r.upper==null?'—':esc(r.upper)} ${esc(r.unit||labDefs[r.analyte].unit)}</span><b>${esc(statusText[r.status]||statusText.unavailable)}</b>${r.reason?`<small>${esc(reasonText[r.reason]||T('Review this measurement and its source','Bu ölçümü ve kaynağını kontrol edin'))}</small>`:''}</article>`).join('')}</div>`:`<p class="footnote">${T('Enable an analyte and enter at least one bound. Empty limits are not zero.','Bir tetkiki etkinleştirip en az bir sınır girin. Boş sınırlar sıfır değildir.')}</p>`}`;
 }
 forms();refresh();
 return {refresh,resetApplicability(){confirmed=false;if($('referenceApplicable'))$('referenceApplicable').checked=false;},restore(record){importGeneration++;if(record!=null)profile=restoreReferenceProfile(record);confirmed=false;notice=record==null?'':'imported';language='';forms();refresh();},
 getDraft(){return {profile:structuredClone(profile),applicabilityConfirmed:false,editorOpen};},
 restoreDraft(data){importGeneration++;profile=referenceDraftProfile(data);confirmed=false;editorOpen=data?.editorOpen===true;notice='draft-restored';language='';forms();refresh();},
 snapshot(){return {...evaluateReferenceProfile(getInput(),profile,{applicabilityConfirmed:confirmed}),applicabilityConfirmed:confirmed};}};
}
